<script setup lang="ts">
// AI 教练浮窗（全站唯一实例，挂载在 App.vue，路由切换不销毁）
//
// 响应式（设计文档 §3）：
// - 桌面端（isDesktop）：右下角固定卡片（宽 400px、高 min(70vh, 640px)），可折叠为圆形气泡；
// - 移动端（isMobile）：整屏 t-drawer，输入区 sticky 于底部并用 dvh 避免软键盘遮挡；
// - 模板分支切换，业务逻辑只写一份（与 App.vue / JudgeJobDetail.vue 的改造模式一致）：
//   两个分支共用同一个 store，浮窗收起/展开不影响正在进行的生成。
//
// 层级：z-index 高于 Monaco 编辑器与既有 t-drawer（本项目头部/侧边栏为 1000）。
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from "vue";
import { useRouter } from "vue-router";
import { LoadingIcon } from "tdesign-icons-vue-next";
import type { AiAction } from "@/apis/ai.ts";
import { useAiCoachStore } from "@/stores/aiCoach.ts";
import type { AiCoachMessage } from "@/stores/aiCoach.ts";
import { useUserStore } from "@/stores/user.ts";
import { useBreakpoint } from "@/composables/useBreakpoint";
import { useCurrentInstance } from "@/util";
import { ShowTextTipsError, ShowTextTipsSuccess } from "@/util/tips";
import { GetText } from "@/text/library.ts";
import { PostJudgeAiParseSave } from "@/apis/judge.ts";
import AiMessageList from "@/components/ai/AiMessageList.vue";

const store = useAiCoachStore();
const userStore = useUserStore();
const router = useRouter();
const { globalProperties } = useCurrentInstance();
const { isMobile } = useBreakpoint();

const isLogin = computed(() => userStore.isLogin());
const sceneTitle = computed(() => store.sceneDisplayTitle);
const inputRef = ref<HTMLTextAreaElement | null>(null);
const messageListRef = ref<InstanceType<typeof AiMessageList> | null>(null);

/** 桌面上浮窗完全关闭或已折叠时，右下角保留圆形入口气泡（全站入口） */
const showBubble = computed(() => (isMobile.value ? !store.visible : !store.visible || store.collapsed));

const modelText = computed(() => {
  const parts = [store.provider, store.model].filter(Boolean);
  return parts.length > 0 ? `：${parts.join(" / ")}` : "";
});

const usageText = computed(() => {
  const usage = store.lastUsage;
  if (!usage) {
    return "";
  }
  return `本轮 token：${usage.total_tokens}（输入 ${usage.prompt_tokens} / 输出 ${usage.completion_tokens}）`;
});

const errorText = computed(() => store.errorMessage);
const canRetry = computed(() => store.messages.some((message) => message.role === "user"));
const canSend = computed(
  () => store.draft.trim().length > 0 && !store.generating && store.sceneEnabled && !store.sceneNotice,
);
const inputDisabled = computed(() => store.generating || !store.sceneEnabled || !!store.sceneNotice);
const inputPlaceholder = computed(() => {
  if (store.sceneNotice) {
    return "当前对象暂不可使用该场景，请查看上方提示";
  }
  if (!store.sceneEnabled) {
    return "当前场景不可用，暂时无法对话";
  }
  if (store.generating) {
    return "AI 正在生成中，可点击「停止」中断";
  }
  return "描述你的问题（Enter 发送 / Shift+Enter 换行）";
});

// ── 输入框聚焦：打开浮窗或 open() 带 autoFocus 时聚焦 ──
async function focusInput() {
  await nextTick();
  inputRef.value?.focus();
}

watch(
  () => store.focusSignal,
  () => {
    void focusInput();
  },
);

watch(
  () => store.visible,
  (visible) => {
    if (visible) {
      void focusInput();
      // 重新展开时贴到底部（此前可能在别处滚动过）
      void messageListRef.value?.scrollToBottom(true);
    }
  },
);

// ── 会话切换下拉（原生实现：项目未使用 t-popup，移动端也不用 tdesign 的 Cell 类组件） ──
const conversationMenuVisible = ref(false);
const conversationMenuRef = ref<HTMLElement | null>(null);

function sceneLabel(key: string) {
  return store.sceneList.find((item) => item.key === key)?.title ?? key;
}

function toggleConversationMenu() {
  conversationMenuVisible.value = !conversationMenuVisible.value;
  if (conversationMenuVisible.value) {
    void store.refreshConversations();
  }
}

async function handleSelectConversation(id: number) {
  conversationMenuVisible.value = false;
  await store.loadConversation(id);
}

function handleClickOutside(event: MouseEvent) {
  if (!conversationMenuVisible.value) {
    return;
  }
  const target = event.target as Node | null;
  if (target && conversationMenuRef.value && !conversationMenuRef.value.contains(target)) {
    conversationMenuVisible.value = false;
  }
}

onMounted(() => {
  document.addEventListener("click", handleClickOutside);
});

onUnmounted(() => {
  document.removeEventListener("click", handleClickOutside);
});

// ── 交互 ──

/** 点入口气泡：恢复上次的会话（场景与引用没变，不会重置） */
function handleOpenEntry() {
  void store.open({ autoFocus: true });
}

function handleSend() {
  if (!canSend.value) {
    return;
  }
  void store.send();
}

function handleStop() {
  store.stop();
}

function handleNewConversation() {
  conversationMenuVisible.value = false;
  store.reset();
  void focusInput();
}

/** 错误提示旁的「重新发送」：把最后一条用户消息再发一次 */
async function handleRetry() {
  const lastUser = [...store.messages].reverse().find((message) => message.role === "user");
  if (!lastUser) {
    return;
  }
  await store.send(lastUser.content);
}

/** 未配置 BYOK：跳用户设置页的「AI 大模型」页签（?tab=8，页签值由设置页做白名单校验） */
function handleGotoSettings() {
  void router.push({ name: "user-modify", query: { tab: "8" } });
}

/**
 * judge_parse_save 的失败文案：错误码优先查项目文案表。
 * 100093 的表文案即「该提交已有 AI 解析，仅提交者可覆盖」，这里再兜一层同义原文，
 * 保证即使文案表缺项也能明确告知原因。
 */
function resolveSaveErrorText(code: number): string {
  if (code > 0) {
    const [found, text] = GetText(code);
    if (found) {
      return text;
    }
  }
  if (code === 100093) {
    return "该提交已有解析，仅提交者可以覆盖";
  }
  return "保存失败，请稍后重试";
}

/**
 * 保存动作处理（judge_parse_save）：
 * 正文取「卡片所在气泡的正文」——即该条 assistant 消息的 content（服务端不持有草稿，只能由前端回传）；
 * 凭证取 payload.receipt（生成正常结束时服务端签发的加密回执，30 分钟有效、与本用户绑定）。
 *
 * 历史消息里的卡片没有 receipt：不调用接口（必然失败），由 AiActionCard 直接禁用并说明，
 * 这里再做一层防御，避免任何入口真的发出无效请求。
 */
async function handleSaveAction(action: AiAction, message: AiCoachMessage) {
  const payload = action.payload ?? {};
  const receipt = typeof payload.receipt === "string" ? payload.receipt.trim() : "";
  const judgeId = Number(payload.judge_id ?? (store.ref.type === "judge" ? store.ref.id : 0)) || 0;
  if (!receipt) {
    ShowTextTipsError(globalProperties, "该保存凭证已失效，请重新生成解析后再保存");
    return;
  }
  if (!judgeId) {
    ShowTextTipsError(globalProperties, "找不到要保存的提交，请在提交详情页重新生成解析");
    return;
  }
  const content = message.content ?? "";
  if (!content.trim()) {
    ShowTextTipsError(globalProperties, "解析正文为空，无法保存");
    return;
  }
  try {
    const res = await PostJudgeAiParseSave(judgeId, content, receipt);
    if (res.code !== 0) {
      ShowTextTipsError(globalProperties, resolveSaveErrorText(res.code));
      return;
    }
    // 成功：卡片置为「已保存」禁用态（动作对象来自 store 消息，改字段即触发重渲染）
    store.markActionSaved(action);
    ShowTextTipsSuccess(globalProperties, "已保存为本次提交的解析");
  } catch (e) {
    console.error("save judge ai parse failed:", e);
    ShowTextTipsError(globalProperties, "保存失败，请稍后重试");
  }
}

/** 动作卡片处理完毕：移动端整屏浮窗会挡住跳转后的页面，这里顺带关闭 */
function handleActionHandled(action: AiAction) {
  if (action.type === "judge_goto" && isMobile.value) {
    store.close();
  }
}
</script>

<template>
  <!-- 未登录不渲染：/ai 系列接口都要求登录态 -->
  <Teleport v-if="isLogin" to="body">
    <!-- 移动端：整屏抽屉 -->
    <t-drawer
      v-if="isMobile"
      class="ai-coach-drawer"
      :visible="store.visible"
      placement="right"
      size="100%"
      :z-index="3300"
      :header="false"
      :footer="false"
      :close-on-overlay-click="true"
      @close="store.close()"
    >
      <div class="ai-coach-sheet">
        <!-- 头部：场景标题 / 会话切换 / 新建 / 关闭 -->
        <div class="ai-coach-head">
          <div class="ai-coach-head-title">
            <t-icon name="chat" />
            <span>{{ sceneTitle }}</span>
          </div>
          <div class="ai-coach-head-actions">
            <div ref="conversationMenuRef" class="ai-coach-conv">
              <button class="ai-coach-icon-btn" title="历史会话" @click="toggleConversationMenu">
                <t-icon name="history" />
              </button>
              <div v-if="conversationMenuVisible" class="ai-coach-conv-menu">
                <div class="ai-coach-conv-head">
                  <span>最近会话</span>
                  <t-button size="small" variant="text" theme="primary" @click="handleNewConversation">新对话</t-button>
                </div>
                <div v-if="store.conversations.length === 0" class="ai-coach-conv-empty">暂无历史会话</div>
                <button
                  v-for="item in store.conversations"
                  :key="item.id"
                  class="ai-coach-conv-item"
                  :class="{ 'is-active': item.id === store.conversationId }"
                  @click="handleSelectConversation(item.id)"
                >
                  <span class="ai-coach-conv-title">{{ item.title || "未命名会话" }}</span>
                  <span class="ai-coach-conv-meta">{{ sceneLabel(item.scene) }} · {{ item.message_count }} 条</span>
                </button>
              </div>
            </div>
            <button class="ai-coach-icon-btn" title="新对话" @click="handleNewConversation"><t-icon name="add" /></button>
            <button class="ai-coach-icon-btn" title="关闭" @click="store.close()"><t-icon name="close" /></button>
          </div>
        </div>

        <AiMessageList
          ref="messageListRef"
          :messages="store.messages"
          :generating="store.generating"
          :save-handler="handleSaveAction"
          @handled="handleActionHandled"
        />

        <!-- 输入区：sticky 底部 + dvh，避免软键盘遮挡 -->
        <div class="ai-coach-foot">
          <!-- 场景提示（详情页带来的禁用原因）优先于场景不可用与请求错误 -->
          <t-alert v-if="store.sceneNotice" theme="warning" :message="store.sceneNotice" />
          <t-alert v-else-if="!store.sceneEnabled" theme="warning" message="当前场景不可用，暂时无法继续对话" />
          <div v-else-if="errorText" class="ai-coach-error">
            <t-alert theme="error" :message="errorText" />
            <t-button v-if="canRetry" size="small" variant="text" theme="primary" @click="handleRetry">重新发送</t-button>
          </div>
          <div v-if="!store.byokReady" class="ai-coach-byok">
            <t-icon name="info-circle" />
            <span>未配置 AI 密钥与模型，发送后会提示去设置</span>
            <t-button size="small" variant="text" theme="primary" @click="handleGotoSettings">去设置</t-button>
          </div>
          <div class="ai-coach-input-row">
            <textarea
              ref="inputRef"
              v-model="store.draft"
              class="ai-coach-input"
              rows="2"
              :disabled="inputDisabled"
              :placeholder="inputPlaceholder"
              @keydown.enter.exact.prevent="handleSend"
            ></textarea>
            <t-button v-if="store.generating" theme="danger" size="small" class="ai-coach-send" @click="handleStop">
              <template #icon><LoadingIcon /></template>
              停止
            </t-button>
            <t-button v-else theme="primary" size="small" class="ai-coach-send" :disabled="!canSend" @click="handleSend">
              <template #icon><t-icon name="send" /></template>
              发送
            </t-button>
          </div>
          <div class="ai-coach-foot-meta">
            <span>当前使用你配置的密钥与模型{{ modelText }}</span>
            <span v-if="usageText" class="ai-coach-foot-usage">{{ usageText }}</span>
          </div>
        </div>
      </div>
    </t-drawer>

    <!-- 桌面端：右下角固定卡片 -->
    <div v-else-if="store.visible && !store.collapsed" class="ai-coach-card">
      <!-- 头部：场景标题 / 会话切换 / 新建 / 折叠 -->
      <div class="ai-coach-head">
        <div class="ai-coach-head-title">
          <t-icon name="chat" />
          <span>{{ sceneTitle }}</span>
        </div>
        <div class="ai-coach-head-actions">
          <div ref="conversationMenuRef" class="ai-coach-conv">
            <button class="ai-coach-icon-btn" title="历史会话" @click="toggleConversationMenu">
              <t-icon name="history" />
            </button>
            <div v-if="conversationMenuVisible" class="ai-coach-conv-menu">
              <div class="ai-coach-conv-head">
                <span>最近会话</span>
                <t-button size="small" variant="text" theme="primary" @click="handleNewConversation">新对话</t-button>
              </div>
              <div v-if="store.conversations.length === 0" class="ai-coach-conv-empty">暂无历史会话</div>
              <button
                v-for="item in store.conversations"
                :key="item.id"
                class="ai-coach-conv-item"
                :class="{ 'is-active': item.id === store.conversationId }"
                @click="handleSelectConversation(item.id)"
              >
                <span class="ai-coach-conv-title">{{ item.title || "未命名会话" }}</span>
                <span class="ai-coach-conv-meta">{{ sceneLabel(item.scene) }} · {{ item.message_count }} 条</span>
              </button>
            </div>
          </div>
          <button class="ai-coach-icon-btn" title="新对话" @click="handleNewConversation"><t-icon name="add" /></button>
          <button class="ai-coach-icon-btn" title="收起为气泡" @click="store.setCollapsed(true)"><t-icon name="chevron-down" /></button>
        </div>
      </div>

      <AiMessageList
        ref="messageListRef"
        :messages="store.messages"
        :generating="store.generating"
        :save-handler="handleSaveAction"
        @handled="handleActionHandled"
      />

      <div class="ai-coach-foot">
        <!-- 场景提示（详情页带来的禁用原因）优先于场景不可用与请求错误 -->
        <t-alert v-if="store.sceneNotice" theme="warning" :message="store.sceneNotice" />
        <t-alert v-else-if="!store.sceneEnabled" theme="warning" message="当前场景不可用，暂时无法继续对话" />
        <div v-else-if="errorText" class="ai-coach-error">
          <t-alert theme="error" :message="errorText" />
          <t-button v-if="canRetry" size="small" variant="text" theme="primary" @click="handleRetry">重新发送</t-button>
        </div>
        <div v-if="!store.byokReady" class="ai-coach-byok">
          <t-icon name="info-circle" />
          <span>未配置 AI 密钥与模型，发送后会提示去设置</span>
          <t-button size="small" variant="text" theme="primary" @click="handleGotoSettings">去设置</t-button>
        </div>
        <div class="ai-coach-input-row">
          <textarea
            ref="inputRef"
            v-model="store.draft"
            class="ai-coach-input"
            rows="2"
            :disabled="inputDisabled"
            :placeholder="inputPlaceholder"
            @keydown.enter.exact.prevent="handleSend"
          ></textarea>
          <t-button v-if="store.generating" theme="danger" size="small" class="ai-coach-send" @click="handleStop">
            <template #icon><LoadingIcon /></template>
            停止
          </t-button>
          <t-button v-else theme="primary" size="small" class="ai-coach-send" :disabled="!canSend" @click="handleSend">
            <template #icon><t-icon name="send" /></template>
            发送
          </t-button>
        </div>
        <div class="ai-coach-foot-meta">
          <span>当前使用你配置的密钥与模型{{ modelText }}</span>
          <span v-if="usageText" class="ai-coach-foot-usage">{{ usageText }}</span>
        </div>
      </div>
    </div>

    <!-- 入口气泡：桌面端常驻右下角，移动端为固定悬浮按钮 -->
    <button v-if="showBubble" class="ai-coach-bubble" :title="store.generating ? 'AI 教练正在生成' : '打开 AI 教练'" @click="handleOpenEntry">
      <t-icon name="chat" size="22px" />
      <span v-if="store.generating" class="ai-coach-bubble-dot"></span>
    </button>
  </Teleport>
</template>

