.ai-coach-error :deep(.t-alert) {
  flex: 1;
}

.ai-coach-byok {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  color: var(--td-text-color-secondary);
}

.ai-coach-input-row {
  display: flex;
  align-items: flex-end;
  gap: 6px;
}

.ai-coach-input {
  flex: 1;
  min-height: 46px;
  max-height: 120px;
  padding: 6px 8px;
  border: 1px solid var(--td-component-border);
  border-radius: var(--td-radius-default);
  background-color: var(--td-bg-color-container);
  color: var(--td-text-color-primary);
  font-family: inherit;
  font-size: 13px;
  line-height: 1.6;
  resize: none;
  outline: none;
}

.ai-coach-input:focus {
  border-color: var(--td-brand-color);
}

.ai-coach-input:disabled {
  background-color: var(--td-bg-color-container-hover);
  color: var(--td-text-color-disabled);
  cursor: not-allowed;
}

.ai-coach-send {
  flex: none;
}

.ai-coach-foot-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-size: 11px;
  color: var(--td-text-color-placeholder);
}

.ai-coach-foot-usage {
  flex: none;
}

/* 移动端：整屏 sheet。抽屉头/尾已关闭，正文区交给 sheet 撑满 */
.ai-coach-sheet {
  display: flex;
  flex-direction: column;
  /* dvh 而非 vh：软键盘弹出时视口高度会变，用 vh 会把输入区顶出屏幕；
     max-height 兜底（抽屉正文有内边距时会比视口略矮） */
  height: 100dvh;
  max-height: 100%;
}

/* 窄屏兜底：低于断点时卡片本身也不该出现（由 v-if 分支保证，这里只防风控） */
@media (max-width: 800px) {
  .ai-coach-card {
    display: none;
  }
}
</style>

<!--
  全局样式（刻意不加 scoped）：t-drawer 的正文由 tdesign 组件自身渲染并被 Teleport 到 body，
  这部分 DOM 不带本组件的 scope 属性，scoped / :deep() 都命中不了。
  类名 ai-coach-drawer 只在本组件使用，因此这条规则不会影响其它抽屉。
-->
<style>
.ai-coach-drawer .t-drawer__body {
  /* 去掉正文内边距，让整屏 sheet 真正铺满 */
  padding: 0;
}
</style>
