export enum UserGender {
  Unknown = 0,
  Male = 1,
  Female = 2,
}

export function GetUserGenderKey(gender: UserGender): string {
  switch (gender) {
    case UserGender.Male:
      return "male";
    case UserGender.Female:
      return "female";
    default:
      return "unkown";
  }
}

export function ParseUser(item: UserInfo): UserInfoView {
  const result: Partial<UserInfoView> = {};
  result.id = item.id;
  result.username = item.username;
  result.nickname = item.nickname;
  result.email = item.email;
  result.slogan = item.slogan;
  result.organization = item.organization;
  result.gender = item.gender;

  if (item.blog != undefined) {
    // 判断item.source是否符合[]()格式，是否赋值result.sourceUrl
    const urlRegex = /\[([^\]]+)\]\(([^)]+)\)/;
    const match = item.blog.match(urlRegex);
    if (match) {
      result.blog = match[1];
      result.blogUrl = match[2];
    } else {
      result.blog = item.blog;
      result.blogUrl = "";
    }
  }

  result.accept = item.accept;
  result.attempt = item.attempt;
  result.vjudgeId = item.vjudge_id;
  result.avatar = GetAvatarUrl(item.username, item.email);

  // 添加等级和经验相关字段
  result.level = item.level || 0;
  result.experience = item.experience || 0;
  result.experience_current_level = item.experience_current_level || 0;
  result.experience_upgrade = item.experience_upgrade || 100;

  // 添加货币字段
  result.coin = item.coin || 0;

  // result 逐字段赋值，此处已填满 UserInfoView 的全部字段
  return result as UserInfoView;
}

