export function GetUserInfo(username: string): Promise<
  CodeResult<{
    user: UserInfo;
    problems_ac?: UserInfoProblemKey[];
    problems_attempt?: UserInfoProblemKey[];
    statics?: UserInfoJudgeStatics[];
  }>
> {
  const params = {
    username: username,
  };
  return httpRequest({
    url: `/user/info?${new URLSearchParams(params).toString()}`,
    method: "get",
  });
}

