/**
 * 测试连接。
 * 传 id 表示测试已保存的密钥；传 provider + apiKey 表示测试尚未保存的密钥。
 * 后端超时 15 秒，这里把 axios 超时放宽到 30 秒以免前端先断
 */
export function PostAiKeyTest(params: { id?: number; provider?: string; apiKey?: string; model?: string }): Promise<CodeResult<AiKeyTestResult>> {
  return httpRequest({
    url: "/user/ai-key/test",
    method: "post",
    timeout: 30000,
    data: {
      id: params.id ?? 0,
      provider: params.provider ?? "",
      api_key: params.apiKey ?? "",
      model: params.model ?? "",
    },
  });
}
