import type { RouteComponent, RouteLocationRaw } from "vue-router";

/** 路由懒加载组件（`() => import("xxx.vue")`）的返回类型 */
type LazyViewComponent = () => Promise<RouteComponent>;

export interface WebStyleState {
  routeTitle: string;
  title: string;
}

export type Tab = {
  name: string;
  path?: string;
  title: string;
  icon?: string;
  showSidebar: boolean;
  disablePath?: boolean;
  disableGenerateTab?: boolean;
  redirect?: string;
  needLogin?: boolean;
  component?: LazyViewComponent;
  auths?: string[]; // 所需要的权限，需要所配置全部的权限才会显示
};

export type View = {
  name: string;
  tab: string;
  sidebar: string;
  path: string;
  title: string;
  icon: string;
  disableTabPath?: boolean;
  disableSidebar?: boolean;
  needLogin?: boolean;
  props?: Record<string, unknown>;
  component: LazyViewComponent;
  auths: string[]; // 所需要的权限，需要所配置全部的权限才会显示
};

export type ViewGroup = {
  title: string;
  children: View[];
};

export type ViewList = (View | ViewGroup)[];

export type MenuGroup = {
  title: string;
  children: Menu[];
};

export type Menu = {
  name: string;
  title: string;
  icon?: string;
  iconClass?: string;
  to?: RouteLocationRaw;
  children?: Menu[];
};

export type MenuList = (Menu | MenuGroup)[];

export function IsViewGroup(item: View | ViewGroup): item is ViewGroup {
  return (item as ViewGroup).children !== undefined;
}

export function IsMenuGroup(item: Menu | MenuGroup): item is MenuGroup {
  return (item as MenuGroup).children !== undefined;
}
